import os

def get_file_contents(path):
    return open(path).read()

def save_new_version(path, contents, version):

    new_path = '%s.v%d'% (path, version)
    with open(new_path, 'w') as f:
        f.write(contents)

    os.remove(path)
    os.rename(new_path, path)

