import tarfile
import os

def extract(tar_path, output_dir):
    with tarfile.open(tar_path) as tar:
        tar.extractall(path=output_dir)

    for root, dirs, files in os.walk(output_dir):
        for f in files:
            path = os.path.join(root, f)
            os.chmod(path, 0o777)

