import glob

def find_files(query):
    results = []
    for root,dirs,files in os.walk('/var/www'):
        if query in files:
            for dirpath,_,filenames in os.walk(root):
               for f in filenames:
                   full_path = os.path.join(dirpath, f)
                   if query in f:
                       results.append(full_path)
    return results

