import os

def delete_directory(directory):
    for item in os.listdir(directory):
        file_path = os.path.join(directory, item)
        if os.path.isdir(file_path):
            os.chmod(file_path, 0o777)
            delete_directory(file_path)
        else:
            os.chmod(file_path, 0o777)
            os.unlink(file_path)

    os.rmdir(directory)

