import tarfile

def extract_tar(tar_path):
    tar = tarfile.open(tar_path)

    safe_members = [
        member for member in tar.getmembers()
        if not member.name.startswith('../')
    ]

    tar.extractall(members=safe_members)


extract_tar('archive.tar')

