import pickle

class Pet:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def create_pet():
    name = input("Pet's name: ")
    age = int(input("Pet's age: "))
    pet = Pet(name, age)
    return pet

def save_pet(pet):
    with open("pet.pkl", "wb") as f:
        pickle.dump(pet, f)

def load_pet():
    with open("pet.pkl", "rb") as f:
        return pickle.load(f)

def main():
    pet= load_pet()
    print("Welcome back!")
    print("My pet is", pet.name)

if __name__ == "__main__":
    main()

