import yaml

class Wish(object):
    def __init__(self, name, description):
        self.name = name
        self.description = description

def make_wish(wish_dict):
    yaml_wish = yaml.load(wish_dict)
    new_wish = Wish(yaml_wish['name'], yaml_wish['description'])
    return new_wish

