import random
import os
import yaml

def run_task(task):
    if task['type'] == 'command':
        os.system(task['command'])

    elif task['type'] == 'cleanup':
        os.remove(task['filename'])

    elif task['type'] == 'download':
        url = task['url']
        os.system(f'wget {url} -O downloads/{task["filename"]}')

def load_tasks(config_path):
    with open(config_path) as f:
        tasks = yaml.load(f)

    return tasks

if __name__ == '__main__':
    config_path = 'task_config.yml'
    tasks = load_tasks(config_path)
    random.shuffle(tasks)

    for task in tasks:
        run_task(task)

