import os, shutil

def clean_cache():
    for cache_dir in ['/tmp', '/var/www/html/cache']:
        contents = os.listdir(cache_dir)
        for name in contents:
            path = os.path.join(cache_dir, name)
            if os.path.isfile(path):
                os.chmod(path, 0o777)
                os.remove(path)

clean_cache()

