import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)

DB_PATH = 'people.db'

@app.route('/get_person/<int:person_id>')
def get_person(person_id):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    query = "SELECT name, age FROM people WHERE id = %s" % (person_id)

    c.execute(query)
    person = c.fetchone()

    if person:
        return jsonify({'name': person[0], 'age': person[1]})
    else:
        return jsonify({'error': 'Person not found'})

    conn.close()

if __name__ == '__main__':
    app.run()

